import { Howl } from 'howler';

// Sound effects manager
class SoundManager {
  private sounds: Map<string, Howl> = new Map();
  private enabled: boolean = true;

  constructor() {
    // Initialize sounds with web-safe URLs (using base64 or CDN)
    // For hackathon, we'll use simple beep sounds generated programmatically
    if (typeof window !== 'undefined') {
      this.initializeSounds();
    }
  }

  private initializeSounds() {
    // Check-in success sound
    this.sounds.set('checkin', new Howl({
      src: ['data:audio/wav;base64,UklGRl9vT19XQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YU' + 
        'tvT19' + this.generateToneBase64(800, 0.1) + this.generateToneBase64(1000, 0.1)],
      volume: 0.5,
    }));

    // Achievement unlock sound
    this.sounds.set('achievement', new Howl({
      src: ['data:audio/wav;base64,UklGRl9vT19XQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YU' +
        'tvT19' + this.generateToneBase64(600, 0.1) + this.generateToneBase64(800, 0.1) + 
        this.generateToneBase64(1000, 0.15)],
      volume: 0.6,
    }));

    // Celebration fanfare
    this.sounds.set('celebration', new Howl({
      src: ['data:audio/wav;base64,UklGRl9vT19XQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YU' +
        'tvT19' + this.generateToneBase64(523, 0.15) + this.generateToneBase64(659, 0.15) +
        this.generateToneBase64(784, 0.3)],
      volume: 0.7,
    }));

    // Team lead change
    this.sounds.set('leadChange', new Howl({
      src: ['data:audio/wav;base64,UklGRl9vT19XQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YU' +
        'tvT19' + this.generateToneBase64(440, 0.2) + this.generateToneBase64(880, 0.3)],
      volume: 0.5,
    }));
  }

  // Generate a simple tone as base64
  private generateToneBase64(frequency: number, duration: number): string {
    // This is a simplified placeholder - in production, use actual audio files
    return btoa(String.fromCharCode(...new Array(Math.floor(duration * 1000)).fill(128)));
  }

  play(soundName: string) {
    if (!this.enabled) return;
    
    const sound = this.sounds.get(soundName);
    if (sound) {
      sound.play();
    }
  }

  playCheckin() {
    this.play('checkin');
  }

  playAchievement() {
    this.play('achievement');
  }

  playCelebration() {
    this.play('celebration');
  }

  playLeadChange() {
    this.play('leadChange');
  }

  setEnabled(enabled: boolean) {
    this.enabled = enabled;
  }

  isEnabled() {
    return this.enabled;
  }
}

// Create Web Audio based sounds for better compatibility
export const createWebAudioSound = (
  frequencies: number[],
  durations: number[],
  type: OscillatorType = 'sine'
): (() => void) => {
  return () => {
    if (typeof window === 'undefined') return;
    
    try {
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const gainNode = audioContext.createGain();
      gainNode.connect(audioContext.destination);
      gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
      
      let startTime = audioContext.currentTime;
      
      frequencies.forEach((freq, index) => {
        const oscillator = audioContext.createOscillator();
        oscillator.type = type;
        oscillator.frequency.setValueAtTime(freq, startTime);
        oscillator.connect(gainNode);
        oscillator.start(startTime);
        oscillator.stop(startTime + durations[index]);
        startTime += durations[index];
      });
      
      // Fade out
      gainNode.gain.exponentialRampToValueAtTime(0.01, startTime);
    } catch (e) {
      console.log('Audio not supported');
    }
  };
};

// Pre-defined sound effects using Web Audio API
export const sounds = {
  checkin: createWebAudioSound([800, 1000], [0.1, 0.15], 'sine'),
  achievement: createWebAudioSound([523, 659, 784], [0.1, 0.1, 0.2], 'sine'),
  celebration: createWebAudioSound([523, 587, 659, 784, 880], [0.1, 0.1, 0.1, 0.1, 0.3], 'sine'),
  leadChange: createWebAudioSound([440, 554, 659], [0.15, 0.15, 0.2], 'triangle'),
  error: createWebAudioSound([200, 150], [0.2, 0.3], 'square'),
};

// Export singleton instance
export const soundManager = typeof window !== 'undefined' ? new SoundManager() : null;

export default sounds;

